	let useCapture;
	let nameLower;
	let proxy;
	let style;
	let styleKey;
	let nextValue;
	let copiedStyles;
	let specialAttrs;
	let listenerKey;
	let xlinkName;
	let xlinkNS;
	let attrName;
	let emptyStyle;
	let dimensionSuffix;
	let emptyListeners;
	let currentListeners;
	let captureFlag;
	let propValue;
	let classAlias;

	emptyStyle = '';
	dimensionSuffix = 'px';
	classAlias = 'class';
	emptyListeners = {};

	if (isSvg && name == 'className') {
		name = classAlias;
	}

	if (name === 'style') {
		style = dom.style;
		if (typeof value == 'string') {
			style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				style.cssText = emptyStyle;
				oldValue = emptyStyle;
			}

			if (oldValue) {
				for (styleKey in oldValue) {
					if (!(value && styleKey in value)) {
						if (styleKey[0] === '-') {
							style.setProperty(styleKey, emptyStyle);
						} else {
							style[styleKey] = emptyStyle;
						}
					}
				}
			}

